// 两域交接以同候选真实军籍、历史公职与明确受命为准，无隐藏第二个军官状态。
#include "political_military_appointment_integration.hpp"
#include "world_bundle.hpp"
#include "resident/domains/military/military_officer_rules.hpp"
#include "resident/domains/military/military_roster_history.hpp"
namespace hanmo::resident {
namespace {
// before回调只接本次业务的四种真实头及实际军事应用头，具名载荷时刻必须完全一致。
bool is_appointment_boundary(const WorldBundle& w,const StableId& id,Integer tick){const auto* h=w.common.state().facts.find(id);if(!h)return false;if(h->domain=="politics"){
 if(h->kind==political_officer_issue_kind){const auto* r=w.political_military_appointments.authorizations.find(id);return r&&r->id==id&&r->tick==tick;}
 if(h->kind==political_officer_accept_kind){const auto* r=w.political_military_appointments.answers.find(id);return r&&r->id==id&&r->accepted&&r->tick==tick;}
 if(h->kind==political_officer_withdraw_kind){const auto* r=w.political_military_appointments.withdrawals.find(id);return r&&r->id==id&&r->tick==tick;}}
 if(h->domain=="military"&&h->kind=="military_officer_assignment")for(const auto& r:w.military.officer_assignments)if(r.id==id)return r.tick==tick;return false;}
PoliticalMilitaryAppointmentUnitRead unit_read(const WorldBundle& w){PoliticalMilitaryAppointmentUnitRead out;
 out.current=[&w](const StableId& id){return query_military_unit_command_source(w.common,w.military,*w.catalog->military,id);};
 out.before_fact=[&w](const StableId& id,Integer tick,const StableId& fact)->Outcome<MilitaryUnitCommandObservation>{if(!is_appointment_boundary(w,fact,tick))return {false,{},common_failure("PoliticalMilitaryHistoryBoundaryRequired",fact).error};auto rosters=military_rosters_before(w.common,w.military,*w.catalog->military,{id},tick,fact,w.population_military_enabled()?&w.population_military:nullptr,w.population_military_enabled()?w.catalog->population_military.get():nullptr);if(!rosters.ok)return {false,{},rosters.error};auto binding=query_military_unit_command_source_before(w.common,w.military,*w.catalog->military,id,fact);if(!binding.ok)return {false,{},binding.error};if(rosters.value.size()!=1||rosters.value.front().id!=id||rosters.value.front().commander_actor_id!=binding.value.commander_actor_id)return {false,{},common_failure("PoliticalMilitaryRosterHistoryMismatch",fact).error};const auto& u=rosters.value.front();return {true,{w.common.state().identity,u.id,u.organization_id,u.garrison_id,u.army_id,u.commander_actor_id,binding.value.command_source},{}};};
 out.garrison_site=[&w](const StableId& id)->std::optional<StableId>{for(const auto& g:w.catalog->military->garrisons)if(g.id==id)return g.place_id;return {};};
 out.at_garrison=[&w](const StableId& id)->Outcome<std::vector<MilitaryUnitCommandObservation>>{std::vector<MilitaryUnitCommandObservation> rows;for(const auto& u:w.military.military_units)if(u.garrison_id==id){auto read=query_military_unit_command_source(w.common,w.military,*w.catalog->military,u.id);if(!read.ok)return {false,{},read.error};rows.push_back(std::move(read.value));if(rows.size()==32)break;}return {true,std::move(rows),{}};};
 out.application_preview=[&w](const StableId& actor,const StableId& auth,const StableId& accept){auto r=preview_military_officer_assignment(w.common,w.military,*w.catalog->military,w.services.military_access(),actor,{"appointment:"+auth,auth,accept,{}});return r.ok?common_success():Status{false,{},r.error};};
 out.application=[&w](const StableId& authorization)->Outcome<std::optional<PoliticalMilitaryApplicationNotice>>{std::optional<PoliticalMilitaryApplicationNotice> out;for(const auto& f:w.military.officer_assignments)if(f.authorization_fact_id==authorization){if(out)return {false,{},common_failure("DuplicateMilitaryOfficerApplication").error};out=PoliticalMilitaryApplicationNotice{f.id,f.authorization_fact_id,f.acceptance_fact_id,f.actor_id,f.tick};}return {true,std::move(out),{}};};
 out.unit_name=[&w](const StableId& id)->Outcome<StableId>{for(const auto& g:w.catalog->military->garrisons)for(const auto& u:g.units)if(u.id==id)return {true,u.display_name.value_or(g.display_name.empty()?StableId{"营中部队"}:g.display_name+"部队"),{}};return {false,{},common_failure("UnknownMilitaryUnit",id).error};};return out;
}
struct ReadScope {PoliticalMilitaryAppointmentUnitRead units;PoliticalMilitaryAppointmentContext context;explicit ReadScope(const WorldBundle& w):units(unit_read(w)),context{w.common,*w.catalog->common,w.organization,*w.catalog->organization,w.local_economy,w.services,*w.catalog->political_military_appointments,w.political_military_appointments,units,w.political_field_appointments_enabled()}{}};
Outcome<std::unique_ptr<ReadScope>> read(const WorldBundle& w){if(!w.political_military_appointments_enabled()||!w.political_military_appointments_seed_complete||!w.politics_enabled()||!w.catalog->organization||!w.catalog->military||!w.catalog->military->officer_assignment_policy)return {false,{},common_failure("PoliticalMilitaryAppointmentProfileRequired").error};return {true,std::make_unique<ReadScope>(w),{}};}
}
Outcome<MilitaryOfficerAppointmentProof> PoliticalMilitaryAppointmentWorldAccess::appointment_for_application(const StableId& auth,const StableId& accept,const StableId& actor)const{auto scope=read(world_);if(!scope.ok)return {false,{},scope.error};return PoliticalMilitaryAppointmentAccess(scope.value->context).appointment_for_application(auth,accept,actor);}
Outcome<MilitaryOfficerAppointmentProof> PoliticalMilitaryAppointmentWorldAccess::appointment_before_application(const StableId& auth,const StableId& accept,const StableId& fact,Integer tick)const{auto scope=read(world_);if(!scope.ok)return {false,{},scope.error};return PoliticalMilitaryAppointmentAccess(scope.value->context).appointment_before_application(auth,accept,fact,tick);}
Outcome<std::optional<DecisionProposal>> propose_political_military_appointment_world(const WorldBundle& w,const KnownSubjectView& known,const DirectorPolicy& policy,const DecisionProposal& base){auto scope=read(w);if(!scope.ok)return {false,{},scope.error};return propose_director_military_appointment(scope.value->context,*w.catalog->travel,known,policy,base);}
Status validate_political_military_appointment_world(const WorldBundle& w){bool enabled=w.political_military_appointments_enabled();auto profile=validate_political_military_appointment_layout(enabled,w.catalog->identity.module_versions,w.political_military_appointments_seed_complete?&w.political_military_appointments:nullptr);if(!profile.ok)return profile;if(w.catalog->director){auto d=validate_political_military_director(*w.catalog->director,w.director,w.catalog->political_military_appointments.get(),enabled?&w.political_military_appointments:nullptr);if(!d.ok)return d;}auto history=validate_political_military_appointment_command_history(w.common,enabled);if(!history.ok)return history;if(!enabled)return w.political_military_appointments.authorizations.empty()&&w.political_military_appointments.answers.empty()&&w.political_military_appointments.withdrawals.empty()?common_success():common_failure("UnexpectedPoliticalMilitaryAppointmentState");auto scope=read(w);if(!scope.ok)return {false,{},scope.error};auto valid=validate_political_military_appointments(scope.value->context);if(!valid.ok)return valid;valid=validate_political_military_appointment_receipts(scope.value->context,[](const CommitResult& r){return r.details&&std::holds_alternative<Done>(r.details->data);});if(!valid.ok)return valid;return validate_military_officer_assignments(w.common,w.military,*w.catalog->military,w.services.military_access());}
Outcome<PoliticalMilitaryAppointmentQuote> prepare_political_military_appointment_world(const WorldBundle& w,const StableId& actor,const PoliticalMilitaryAppointmentCommand& command){auto scope=read(w);if(!scope.ok)return {false,{},scope.error};return preview_political_military_appointment(scope.value->context,actor,command);}
Outcome<StableId> commit_political_military_appointment_world(WorldBundle& w,const StableId& actor,const PoliticalMilitaryAppointmentCommand& command,const PoliticalMilitaryAppointmentQuote& quote){auto scope=read(w);if(!scope.ok)return {false,{},scope.error};return apply_political_military_appointment_in_transaction(w.common,w.political_military_appointments,scope.value->context,actor,command,quote);}
Outcome<BoundaryValue> merge_political_military_appointment_world_page(const WorldBundle& w,const StableId& actor,const StableId& site,BoundaryValue page){if(!w.political_military_appointments_enabled())return {true,std::move(page),{}};auto scope=read(w);if(!scope.ok)return {false,{},scope.error};return merge_political_military_appointment_page(scope.value->context,actor,site,std::move(page));}
}
